#include <QCoreApplication>
#include <QTemporaryDir>
#include <QProcess>
#include <QTcpServer>
#include <QTcpSocket>
#include <QElapsedTimer>
#include <QThread>
#include <QDebug>
#include <QSqlQuery>
#include <functional>
#include <cstdlib>
#include "../src/db/DatabaseManager.h"
#include "../src/sync/SyncStorage.h"
#include "../src/sync/SyncEngine.h"
void require(bool c,const char* message){if(!c){qCritical()<<message<<SyncEngine::instance().status()<<SyncStorage::lastError();std::exit(1);}}
bool until(std::function<bool()> predicate,int timeout=10000){QElapsedTimer t;t.start();while(t.elapsed()<timeout){QCoreApplication::processEvents();if(predicate())return true;QThread::msleep(10);}return false;}
int main(int argc,char** argv){
    QCoreApplication app(argc,argv);QTemporaryDir temp;require(argc==3,"python and source path required");qputenv("LAPTOPS_DATA_DIR",temp.path().toUtf8());qputenv("LAPTOPS_SYNC_TEST","1");auto& db=DatabaseManager::instance();require(db.initDatabase(),"db initialization");QTcpServer port;require(port.listen(QHostAddress::LocalHost,0),"reserve port");int number=port.serverPort();port.close();
    QProcess server;server.setWorkingDirectory(QString::fromLocal8Bit(argv[2]));server.setProcessChannelMode(QProcess::MergedChannels);
    auto start=[&]{server.start(QString::fromLocal8Bit(argv[1]),{"-m","server.test_fixture","--db",temp.filePath("server.db"),"--port",QString::number(number)});require(server.waitForStarted(),"fixture process started");QElapsedTimer boot;boot.start();bool ready=false;while(boot.elapsed()<10000){QTcpSocket probe;probe.connectToHost(QHostAddress::LocalHost,number);if(probe.waitForConnected(100)){ready=true;break;}QThread::msleep(50);}require(ready,"fixture listener ready");};start();
    SyncStorage::setSetting("endpoint","http://127.0.0.1:"+QString::number(number));auto& sync=SyncEngine::instance();sync.start();sync.login("admin","integration-test-password");require(until([&]{return sync.status().startsWith("متصل");}),"real login/snapshot");require(db.getStockTypes().isEmpty(),"server owns presets");
    StockType type;type.name="Network cable";require(db.saveStockType(type),"queued type");InventoryItem item;item.typeId=type.id;item.name="USB";item.total=4;require(db.saveInventoryItem(item),"queued item and event");require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");}),"upload bootstrap transactions");require(SyncStorage::count("conflict")==0,"no bootstrap conflicts");
    QSqlQuery itemIdentity(SyncStorage::database());itemIdentity.prepare("SELECT global_id FROM sync_ids WHERE table_name='inventory_items' AND local_id=?");itemIdentity.addBindValue(item.id);require(itemIdentity.exec()&&itemIdentity.next(),"item global identity");QString itemGlobal=itemIdentity.value(0).toString();itemIdentity.finish();
    server.kill();server.waitForFinished();auto offlineItem=db.getInventoryItems()[0];offlineItem.description="My offline description";require(db.saveInventoryItem(offlineItem),"offline description edit queued");require(until([&]{return sync.status().startsWith("آفلاین");}),"description offline state");start();
    QProcess editor;editor.setWorkingDirectory(QString::fromLocal8Bit(argv[2]));editor.start(QString::fromLocal8Bit(argv[1]),{"-m","server.test_peer","--port",QString::number(number),"--edit-item",itemGlobal});require(editor.waitForFinished(10000)&&editor.exitCode()==0,"peer updates same description and another field while this client is offline");require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");},20000),"offline stale description automatically uploads without manual retry");require(SyncStorage::count("conflict")==0,"forced description requires no settings review");auto merged=db.getInventoryItems()[0];require(merged.description=="My offline description"&&merged.location=="Peer shelf","my edited field wins while peer untouched field survives");
    require(db.lendInventory(item.id,1,"Lost reply borrower"),"single-unit lend before lost ack");require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");}),"single-unit lend auto uploaded");int completedLoan=db.getInventoryLoans()[0].id;require(db.returnInventory(completedLoan,1,"Returner"),"full return whose reply is lost");require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");},20000),"full return recovered automatically from committed feed");require(SyncStorage::count("conflict")==0&&db.getInventoryItems()[0].available()==4,"lost full-return ack neither duplicates counters nor creates false review");
    server.kill();server.waitForFinished();require(db.lendInventory(item.id,3,"Offline borrower"),"offline mutation");int lid=db.getInventoryLoans()[0].id;require(db.returnInventory(lid,1,"Returner"),"offline dependent return");require(until([&]{return sync.status().startsWith("آفلاین");}),"network failure visible");require(SyncStorage::count("pending")==2,"offline commands preserved");require(SyncStorage::initialize(SyncStorage::database()),"reopen durable storage");start();require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");},20000),"reconnect flushes dependency chain");require(SyncStorage::count("conflict")==0,"no return conflicts");auto stock=db.getInventoryItems()[0];require(stock.loaned==2&&stock.available()==2,"exact stock after reconnect");
    server.kill();server.waitForFinished();
    LoanRecord edited;edited.teacherName="Teacher";edited.recipientName="Original";edited.laptopNumber="OFFLINE-EDIT";edited.initialCondition="Healthy";edited.gradeLevel="Grade";require(db.addLoan(edited),"offline laptop create");edited.recipientName="Edited offline";edited.notes="Offline full edit";edited.returnerName.clear();edited.returnCondition.clear();require(db.updateLoan(edited),"full active record edit saves offline");require(SyncStorage::count("pending")==2,"offline create and edit are durable");start();require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");},20000),"offline full edit uploads automatically");require(SyncStorage::count("conflict")==0&&db.getActiveLoans()[0].recipientName=="Edited offline","full edit preserved on server projection");require(db.deleteLoan(edited.id),"remove test edit");require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");}),"test edit deleted");
    require(db.reportMissingStock(item.id,1,"Reporter","Missing cable",lid),"loss report");require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");}),"missing upload");int missing=db.getMissingStockReports()[0].id;require(db.recoverMissingStock(missing,1,"Finder"),"recovery");require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");}),"recovery upload");require(SyncStorage::count("conflict")==0,"no inventory conflicts");stock=db.getInventoryItems()[0];require(stock.loaned==1&&stock.missing==0&&stock.available()==3,"loss/recovery stock invariant");
    LoanRecord laptop;laptop.teacherName="Teacher";laptop.recipientName="Recipient";laptop.laptopNumber="NETWORK-LAPTOP";laptop.initialCondition="Healthy";laptop.gradeLevel="Grade";
    require(db.addLoan(laptop),"laptop create");require(db.updateLoanNotes(laptop.id,"Offline note"),"laptop note dependency");require(db.returnLoan(laptop.id,"Returner","Healthy"),"laptop return dependency");require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");}),"laptop loans/notes/returns upload");require(SyncStorage::count("conflict")==0,"no laptop conflicts");require(db.getDeliveredLoans().size()==1&&db.getDeliveredLoans()[0].notes=="Offline note","laptop archived correctly");
    require(db.deleteLoan(laptop.id),"laptop deletion");require(until([&]{return SyncStorage::count("pending")==0&&sync.status().startsWith("متصل");}),"laptop tombstone upload");require(db.getAllLoans().isEmpty(),"laptop deletion projected");
    QProcess peer;peer.setWorkingDirectory(QString::fromLocal8Bit(argv[2]));peer.start(QString::fromLocal8Bit(argv[1]),{"-m","server.test_peer","--port",QString::number(number)});require(peer.waitForFinished(10000)&&peer.exitCode()==0,"another user's laptop lend and return");require(until([&]{return db.getDeliveredLoans().size()==1&&db.getDeliveredLoans()[0].notes=="Archive from another user";},15000),"automatic incoming archive update without pressing Sync");
    sync.logout();require(!db.lendInventory(item.id,1,"P"),"logout blocks local writes");server.kill();server.waitForFinished();qInfo()<<"Real Qt HTTP sync passed: login, atomic uploads, offline failure/reconnect, counters, and logout.";
}
